pub type Grade = enum {
  Letter(score: Int),
}

fn pass_fail(g: &Grade) -> Str {
  match g {
    Letter(s) if s >= 60 => { return "Pass"; }
    Letter(s) => { return "Fail"; }
  }
}

fn honors(g: &Grade) -> Str {
  match g {
    Letter(s) if s >= 90 => { return "Summa Cum Laude"; }
    Letter(s) if s >= 80 => { return "Magna Cum Laude"; }
    Letter(s) if s >= 70 => { return "Cum Laude"; }
    Letter(_) => { return "None"; }
  }
}

fn main() -> Int {
  let g1 = Grade.Letter(95);
  let g2 = Grade.Letter(85);
  let g3 = Grade.Letter(55);
  var count = 0;
  if pass_fail(&g1) == "Pass" { count = count + 1; }
  if pass_fail(&g2) == "Pass" { count = count + 1; }
  if pass_fail(&g3) == "Pass" { count = count + 1; }
  return count;
}
